/**
 * @fileoverview Input blocker utilities for guarding against user interference
 * during automated browser operations.
 *
 * Provides functions to inject and remove a full-viewport overlay that
 * intercepts user input (clicks, key presses, scrolling) while the AI agent is
 * driving the page. The overlay is briefly suspended around each automated
 * interactive action so the automation itself can reach the underlying page,
 * then resumed afterwards.
 *
 * The script strings are passed to chrome-devtools-mcp's evaluate_script tool
 * which expects a plain function expression (NOT an IIFE).
 */

import type { BrowserManager } from './browserManager.js';
import { debugLogger } from '../../utils/debugLogger.js';

const BLOCKER_ELEMENT_ID = '__gemini_input_blocker';

/**
 * Builds the JavaScript function string that injects the input-blocking
 * overlay.
 *
 * Returns a plain arrow-function expression (no trailing invocation) because
 * chrome-devtools-mcp's evaluate_script tool invokes it internally.
 */
function buildInjectionScript(): string {
  return `() => {
    const id = '${BLOCKER_ELEMENT_ID}';
    const existing = document.getElementById(id);
    if (existing) existing.remove();

    const blocker = document.createElement('div');
    blocker.id = id;
    blocker.setAttribute('aria-hidden', 'true');
    blocker.setAttribute('role', 'presentation');
    blocker.setAttribute('title', 'Gemini CLI is controlling this browser');

    Object.assign(blocker.style, {
      position: 'fixed',
      top: '0',
      left: '0',
      right: '0',
      bottom: '0',
      zIndex: '2147483646',
      pointerEvents: 'auto',
      cursor: 'not-allowed',
      background: 'transparent',
    });

    const label = document.createElement('div');
    label.textContent = 'Gemini CLI is controlling this browser';
    Object.assign(label.style, {
      position: 'fixed',
      top: '8px',
      left: '50%',
      transform: 'translateX(-50%)',
      padding: '4px 12px',
      borderRadius: '12px',
      background: 'rgba(66,133,244,0.9)',
      color: 'white',
      font: '12px sans-serif',
      pointerEvents: 'none',
    });
    blocker.appendChild(label);

    const swallow = (e) => {
      e.preventDefault();
      e.stopPropagation();
    };
    const events = [
      'click', 'dblclick', 'mousedown', 'mouseup', 'contextmenu',
      'keydown', 'keyup', 'keypress', 'wheel', 'touchstart', 'touchmove',
    ];
    events.forEach((type) => blocker.addEventListener(type, swallow, true));

    document.documentElement.appendChild(blocker);

    return 'input-blocker-injected';
  }`;
}

/**
 * Builds the JavaScript function string that temporarily suspends the input
 * blocker so an automated action can reach the underlying page.
 */
function buildSuspendScript(): string {
  return `() => {
    const el = document.getElementById('${BLOCKER_ELEMENT_ID}');
    if (el) {
      el.style.pointerEvents = 'none';
      el.style.display = 'none';
    }
    return 'input-blocker-suspended';
  }`;
}

/**
 * Builds the JavaScript function string that resumes the input blocker after
 * an automated action has completed.
 */
function buildResumeScript(): string {
  return `() => {
    const el = document.getElementById('${BLOCKER_ELEMENT_ID}');
    if (el) {
      el.style.pointerEvents = 'auto';
      el.style.display = 'block';
    }
    return 'input-blocker-resumed';
  }`;
}

/**
 * Builds the JavaScript function string that removes the input blocker.
 */
function buildRemovalScript(): string {
  return `() => {
    const el = document.getElementById('${BLOCKER_ELEMENT_ID}');
    if (el) el.remove();
    return 'input-blocker-removed';
  }`;
}

/**
 * Injects the input-blocking overlay into the current page.
 *
 * Resolves with `undefined` even when the underlying tool call throws, so the
 * caller never has to guard against injection failures.
 */
export async function injectInputBlocker(
  browserManager: BrowserManager,
  signal?: AbortSignal,
): Promise<void> {
  try {
    debugLogger.log('Injecting input blocker...');

    const result = await browserManager.callTool(
      'evaluate_script',
      { function: buildInjectionScript() },
      signal,
    );

    if (result.isError) {
      debugLogger.warn('Failed to inject input blocker:', result);
    } else {
      debugLogger.log('Input blocker injected successfully');
    }
  } catch (error) {
    debugLogger.warn('Error injecting input blocker:', error);
  }
}

/**
 * Removes the input-blocking overlay from the current page.
 *
 * Resolves with `undefined` even when the underlying tool call throws, so the
 * caller can always safely await removal in a cleanup path.
 */
export async function removeInputBlocker(
  browserManager: BrowserManager,
  signal?: AbortSignal,
): Promise<void> {
  try {
    debugLogger.log('Removing input blocker...');

    const result = await browserManager.callTool(
      'evaluate_script',
      { function: buildRemovalScript() },
      signal,
    );

    if (result.isError) {
      debugLogger.warn('Failed to remove input blocker:', result);
    } else {
      debugLogger.log('Input blocker removed successfully');
    }
  } catch (error) {
    debugLogger.warn('Error removing input blocker:', error);
  }
}

/**
 * Suspends the input blocker so an automated interactive action can reach the
 * underlying page. Never throws.
 */
export async function suspendInputBlocker(
  browserManager: BrowserManager,
  signal?: AbortSignal,
): Promise<void> {
  try {
    await browserManager.callTool(
      'evaluate_script',
      { function: buildSuspendScript() },
      signal,
    );
  } catch (error) {
    debugLogger.warn('Error suspending input blocker:', error);
  }
}

/**
 * Resumes the input blocker after an automated interactive action has finished.
 * Never throws.
 */
export async function resumeInputBlocker(
  browserManager: BrowserManager,
  signal?: AbortSignal,
): Promise<void> {
  try {
    await browserManager.callTool(
      'evaluate_script',
      { function: buildResumeScript() },
      signal,
    );
  } catch (error) {
    debugLogger.warn('Error resuming input blocker:', error);
  }
}
